 */
public object FfiConverterTypeSafetyEngine: FfiConverter<SafetyEngine, Pointer> {

    override fun lower(value: SafetyEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): SafetyEngine {
        return SafetyEngine(value)
    }

    override fun read(buf: ByteBuffer): SafetyEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: SafetyEngine) = 8UL

    override fun write(value: SafetyEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



